/* Amber Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="amber-minimal-light"] {
  --background: rgb(255, 255, 255);
  --foreground: rgb(38, 38, 38);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(38, 38, 38);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(38, 38, 38);
  --primary: rgb(244, 159, 30);
  --primary-foreground: rgb(0, 0, 0);
  --secondary: rgb(245, 245, 245);
  --secondary-foreground: rgb(75, 86, 102);
  --muted: rgb(248, 248, 248);
  --muted-foreground: rgb(108, 114, 126);
  --accent: rgb(255, 252, 240);
  --accent-foreground: rgb(143, 65, 19);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(228, 232, 239);
  --input: rgb(228, 232, 239);
  --ring: rgb(244, 159, 30);
  --chart-1: rgb(244, 159, 30);
  --chart-2: rgb(219, 120, 0);
  --chart-3: rgb(183, 83, 1);
  --chart-4: rgb(143, 65, 19);
  --chart-5: rgb(121, 50, 7);
  --radius: 0.375rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(38, 38, 38);
  --sidebar-primary: rgb(244, 159, 30);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(255, 252, 240);
  --sidebar-accent-foreground: rgb(143, 65, 19);
  --sidebar-border: rgb(228, 232, 239);
  --sidebar-ring: rgb(244, 159, 30);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="amber-minimal-dark"] {
  --background: rgb(22, 22, 22);
  --foreground: rgb(228, 228, 228);
  --card: rgb(38, 38, 38);
  --card-foreground: rgb(228, 228, 228);
  --popover: rgb(38, 38, 38);
  --popover-foreground: rgb(228, 228, 228);
  --primary: rgb(244, 159, 30);
  --primary-foreground: rgb(0, 0, 0);
  --secondary: rgb(38, 38, 38);
  --secondary-foreground: rgb(228, 228, 228);
  --muted: rgb(38, 38, 38);
  --muted-foreground: rgb(164, 164, 164);
  --accent: rgb(143, 65, 19);
  --accent-foreground: rgb(253, 228, 132);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(64, 64, 64);
  --input: rgb(64, 64, 64);
  --ring: rgb(244, 159, 30);
  --chart-1: rgb(251, 192, 49);
  --chart-2: rgb(219, 120, 0);
  --chart-3: rgb(143, 65, 19);
  --chart-4: rgb(183, 83, 1);
  --chart-5: rgb(143, 65, 19);
  --radius: 0.375rem;
  --sidebar: rgb(15, 15, 15);
  --sidebar-foreground: rgb(228, 228, 228);
  --sidebar-primary: rgb(244, 159, 30);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(143, 65, 19);
  --sidebar-accent-foreground: rgb(253, 228, 132);
  --sidebar-border: rgb(64, 64, 64);
  --sidebar-ring: rgb(244, 159, 30);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
}
